<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { downloadFile, json, request } from '../api/client'

const { t } = useI18n()
const client = useQueryClient()
const chatsQuery = useQuery({ queryKey: ['export-chats'], queryFn: () => request<any[]>('/api/v1/exports/chats'), retry: false })
const tasksQuery = useQuery({ queryKey: ['export-tasks'], queryFn: () => request<any[]>('/api/v1/exports/tasks'), refetchInterval: 10000 })
const runsQuery = useQuery({ queryKey: ['export-runs'], queryFn: () => request<any[]>('/api/v1/exports/runs?limit=30'), refetchInterval: 10000 })
const jobId = ref('')
const jobQuery = useQuery({ queryKey: computed(() => ['export-job', jobId.value]), queryFn: () => request<any>(`/api/v1/exports/jobs/${jobId.value}`), enabled: computed(() => Boolean(jobId.value)), refetchInterval: query => ['completed','failed','cancelled'].includes((query.state.data as any)?.status) ? false : 1000 })
const messageForm = reactive({ chat_id: '', start_at: '', end_at: '', formats: ['json','html','sqlite'], subdirectory: 'messages', all_history: false })
const taskOpen = ref(false)
const taskForm = reactive({ name: '', chat_id: '', initial_start_at: '', formats: ['json','html','sqlite'], subdirectory: 'scheduled', schedule_type: 'daily', minute: 0, hour: 2, weekday: 0, timezone: 'Asia/Shanghai', all_history: false, enabled: true })
const startMessage = useMutation({ mutationFn: () => request<{job_id:string}>('/api/v1/exports/jobs/messages', json('POST', { ...messageForm, chat_id: Number(messageForm.chat_id), start_at: messageForm.start_at || null, end_at: messageForm.end_at || null })), onSuccess: data => { jobId.value = data.job_id } })
const saveTask = useMutation({ mutationFn: () => request('/api/v1/exports/tasks', json('POST', { ...taskForm, chat_id: Number(taskForm.chat_id), initial_start_at: taskForm.initial_start_at || null })), onSuccess: () => { taskOpen.value=false; client.invalidateQueries({queryKey:['export-tasks']}) } })
const removeTask = useMutation({ mutationFn: (id:number) => request(`/api/v1/exports/tasks/${id}`, json('DELETE')), onSuccess: () => client.invalidateQueries({queryKey:['export-tasks']}) })
async function runTask(id:number) { const result = await request<{job_id:string}>(`/api/v1/exports/tasks/${id}/run`, json('POST')); jobId.value=result.job_id }
function downloadExport(path:string) { return downloadFile(`/api/v1/exports/file?path=${encodeURIComponent(path)}`, path.split('/').pop() ?? 'export') }
function removeScheduledTask(id:number) { if (window.confirm(t('common.confirmDelete'))) removeTask.mutate(id) }
</script>

<template><section><header class="page-heading"><div><p class="eyebrow">ARCHIVE PIPELINE / SQLITE + FILE</p><h1>{{ t('exports.title') }}</h1><p>{{ t('exports.subtitle') }}</p></div><button class="primary-button compact" @click="taskOpen=true">NEW SCHEDULE ＋</button></header><div class="content-grid"><article class="panel"><div class="panel-heading"><h2>ONE-OFF MESSAGE EXPORT</h2><span>{{ chatsQuery.data.value?.length ?? 0 }} CHATS</span></div><form class="form-grid" @submit.prevent="startMessage.mutate()"><label class="full">CHAT<select v-model="messageForm.chat_id" required><option value="" disabled>Select chat</option><option v-for="chat in chatsQuery.data.value" :key="chat.chat_id" :value="chat.chat_id">{{ chat.label }}</option></select></label><label>START<input v-model="messageForm.start_at" type="datetime-local" :disabled="messageForm.all_history"></label><label>END<input v-model="messageForm.end_at" type="datetime-local"></label><label class="full">SUBDIRECTORY<input v-model="messageForm.subdirectory"></label><div class="full check-row"><label v-for="format in ['json','csv','html','sqlite']" :key="format"><input v-model="messageForm.formats" type="checkbox" :value="format">{{ format.toUpperCase() }}</label><label><input v-model="messageForm.all_history" type="checkbox">ALL HISTORY</label></div><button class="primary-button compact">START EXPORT ↗</button></form><p v-if="chatsQuery.error.value" class="form-error">Connect Telegram to load chats.</p></article><article class="panel"><div class="panel-heading"><h2>ACTIVE JOB</h2><span>{{ jobQuery.data.value?.status?.toUpperCase() || 'IDLE' }}</span></div><template v-if="jobQuery.data.value"><strong style="font-size:26px">{{ jobQuery.data.value.processed }}<small v-if="jobQuery.data.value.total"> / {{ jobQuery.data.value.total }}</small></strong><p style="color:var(--muted);font-size:11px">{{ jobQuery.data.value.phase }} · {{ jobQuery.data.value.id }}</p><div class="health-bar"><i :style="{width:jobQuery.data.value.total?`${jobQuery.data.value.processed/jobQuery.data.value.total*100}%`:'18%'}"></i></div><div class="form-section"><button v-for="file in jobQuery.data.value.files" :key="file" class="tag" type="button" style="margin:0 6px 6px 0" @click="downloadExport(file)">{{ file.split('/').pop() }} ↗</button></div></template><p v-else class="empty-state">NO ACTIVE EXPORT</p></article></div><article class="panel table-panel" style="margin-top:13px"><div class="panel-heading"><h2>SCHEDULED EXPORTS</h2><span>{{ tasksQuery.data.value?.length ?? 0 }} TASKS</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>TASK</th><th>CHAT</th><th>SCHEDULE</th><th>FORMATS</th><th>NEXT RUN</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="task in tasksQuery.data.value" :key="task.id"><td><strong>{{ task.name }}</strong><br><span class="tag" :class="{off:!task.enabled}">{{ task.enabled?'ACTIVE':'PAUSED' }}</span></td><td>{{ task.chat_title }}<br>{{ task.chat_id }}</td><td>{{ task.schedule_type }} · {{ String(task.hour).padStart(2,'0') }}:{{ String(task.minute).padStart(2,'0') }}</td><td>{{ task.formats.join(', ') }}</td><td>{{ task.next_run_at || '—' }}</td><td><div class="action-row"><button class="icon-action" @click="runTask(task.id)">RUN</button><button class="icon-action" @click="removeScheduledTask(task.id)">DELETE</button></div></td></tr></tbody></table><p v-if="!tasksQuery.data.value?.length" class="empty-state">{{ t('common.noData') }}</p></div></article><article class="panel table-panel" style="margin-top:13px"><div class="panel-heading"><h2>RUN HISTORY</h2><span>LAST 30</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>STARTED</th><th>TYPE</th><th>CHAT</th><th>STATUS</th><th>COUNT</th><th>FILES</th></tr></thead><tbody><tr v-for="run in runsQuery.data.value" :key="run.id"><td>{{ run.started_at }}</td><td>{{ run.run_type }}</td><td>{{ run.chat_title || run.chat_id || '—' }}</td><td><span class="tag" :class="{off:run.status!=='completed'}">{{ run.status }}</span></td><td>{{ run.message_count }}</td><td><button v-for="file in run.files" :key="file" class="tag" type="button" style="margin-right:4px" @click="downloadExport(file)">FILE ↗</button></td></tr></tbody></table></div></article><div v-if="taskOpen" class="drawer" @click.self="taskOpen=false"><form class="drawer-panel" @submit.prevent="saveTask.mutate()"><div class="drawer-heading"><div><p class="eyebrow">SCHEDULER</p><h2>New export task</h2></div><button type="button" class="drawer-close" @click="taskOpen=false">×</button></div><div class="form-grid"><label class="full">NAME<input v-model="taskForm.name" required></label><label class="full">CHAT<select v-model="taskForm.chat_id" required><option v-for="chat in chatsQuery.data.value" :key="chat.chat_id" :value="chat.chat_id">{{ chat.label }}</option></select></label><label>INITIAL START<input v-model="taskForm.initial_start_at" type="datetime-local" :disabled="taskForm.all_history"></label><label>TIMEZONE<input v-model="taskForm.timezone"></label><label>SCHEDULE<select v-model="taskForm.schedule_type"><option value="hourly">Hourly</option><option value="daily">Daily</option><option value="weekly">Weekly</option></select></label><label>HOUR<input v-model.number="taskForm.hour" type="number" min="0" max="23"></label><label>MINUTE<input v-model.number="taskForm.minute" type="number" min="0" max="59"></label><label>WEEKDAY<input v-model.number="taskForm.weekday" type="number" min="0" max="6"></label><label class="full">SUBDIRECTORY<input v-model="taskForm.subdirectory"></label></div><div class="form-section check-row"><label v-for="format in ['json','csv','html','sqlite']" :key="format"><input v-model="taskForm.formats" type="checkbox" :value="format">{{ format.toUpperCase() }}</label><label><input v-model="taskForm.all_history" type="checkbox">ALL HISTORY</label><label><input v-model="taskForm.enabled" type="checkbox">ENABLED</label></div><p v-if="saveTask.error.value" class="form-error">{{ saveTask.error.value.message }}</p><div class="form-section control-row"><button type="button" class="ghost-button" @click="taskOpen=false">CANCEL</button><button class="primary-button compact">SAVE TASK ↗</button></div></form></div></section></template>
